# frozen_string_literal: true

require "minitest/autorun"
require "tmpdir"
require "dependency_update"

class HoldBackYoungLockEntriesTest < Minitest::Test
  LOCKFILE = <<~LOCK
    # THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.
    # yarn lockfile v1


    browserslist@^4.29.0:
      version "4.29.5"
      resolved "https://registry.yarnpkg.com/browserslist/-/browserslist-4.29.5.tgz#b5"
      integrity sha512-b5==
      dependencies:
        node-releases "^2.0.60"

    node-releases@^2.0.60:
      version "2.0.60"
      resolved "https://registry.yarnpkg.com/node-releases/-/node-releases-2.0.60.tgz#n60"
      integrity sha512-n60==
  LOCK

  class YarnInstallStub < DependencyUpdate::Runner
    def system(*)
      File.write("yarn.lock", File.read("yarn.lock").sub("node-releases@^2.0.60:", "node-releases@^2.0.59:"))
    end
  end

  def test_rechecks_an_entry_once_its_ranges_have_loosened
    Dir.mktmpdir do |dir|
      Dir.chdir(dir) do
        File.write("yarn.lock", LOCKFILE)

        held = runner.send(:hold_back_young_lock_entries, { "browserslist" => ["4.29.4"], "node-releases" => ["2.0.59"] })

        assert_equal "4.29.4", held["browserslist"][:best]
        assert_equal "2.0.59", held["node-releases"][:best]
        assert_includes File.read("yarn.lock"), %(version "2.0.59")
      end
    end
  end

  private

  def runner
    YarnInstallStub.new.tap do |runner|
      runner.instance_variable_set(:@npm_cache, {
        "browserslist" => registry_data("browserslist", "4.29.4" => [30, { "node-releases" => "^2.0.59" }], "4.29.5" => [2, { "node-releases" => "^2.0.60" }]),
        "node-releases" => registry_data("node-releases", "2.0.59" => [13, {}], "2.0.60" => [6, {}])
      })
    end
  end

  def registry_data(name, versions)
    {
      "time" => versions.transform_values { |(days_ago, _)| (Time.now - (days_ago * 86400)).iso8601 },
      "versions" => versions.to_h do |version, (_, dependencies)|
        [version, {
          "dependencies" => dependencies,
          "dist" => { "tarball" => "https://registry.npmjs.org/#{name}/-/#{name}-#{version}.tgz", "shasum" => "s#{version}", "integrity" => "sha512-#{version}==" }
        }]
      end
    }
  end
end
